(function(){
'use strict';
const {GameEngine,TYPES,MISSIONS,GRID,PLAYABLE,UPGRADES,coord,parseCoord,col,dist,clamp,newProfile,cleanProfile,buy,reward}=window.IronTide;
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=t=>Math.floor(Math.max(0,t)/60).toString().padStart(2,'0')+':'+Math.floor(Math.max(0,t)%60).toString().padStart(2,'0');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch(e){return fallback;}};
let storageOK=true;const write=(key,v)=>{try{localStorage.setItem(key,JSON.stringify(v));}catch(e){storageOK=false;}};
let profile=cleanProfile(read('iron-tide-profile-v2',newProfile())),prefs={master:.65,music:.30,effects:.75,mute:false,...read('iron-tide-audio-v2',{})};
let chosenType=profile.selected,chosenMission=0,difficulty='normal',nickname=read('iron-tide-name-v2','กัปตัน'),lastSave=read('iron-tide-save-v2',null),hasSession=false,online=false,room=null,modalMode='menu',returnView=null,selectedTarget=null,localAim=null,lastEnd=null,last=0,uiClock=0,netClock=0,saveClock=0,toastTimer=0,lastEvents=0,hadConnection=false,lastRoomView='',keys=new Set(),heldGun=false,previousMode=null;
const engine=new GameEngine();engine.start(0);const view=new window.IronTideRenderer($('world'),engine),audio=new window.IronTideAudio(prefs),net=new window.IronTideNetwork();
const radar=$('radar'),rctx=radar.getContext('2d'),overlay=$('overlay'),octx=overlay.getContext('2d');
view.quality=clamp(read('iron-tide-quality-v2',2),0,2);
const myShip=()=>engine.state?.ships.find(s=>s.id===engine.state.selected);
const pilot=()=>({id:'local',name:nickname||'กัปตัน',type:chosenType,upgrades:profile.upgrades[chosenType]||{}});
function toast(text,error=false){$('toast').textContent=text;$('toast').className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3300);}
function persistProfile(){write('iron-tide-profile-v2',profile);}
function saveGame(){if(online||!hasSession)return;lastSave=engine.export();write('iron-tide-save-v2',lastSave);}
function stopKeys(){keys.clear();heldGun=false;const sh=myShip();if(sh){if(online)net.send({throttle:0,steer:0},sh.aim);else engine.input(sh.id,{throttle:0,steer:0});}}
function show(html,mode,wide=false){stopKeys();modalMode=mode;if(!online)engine.state.running=false;$('modal-card').className='modal-card'+(wide?' wide':'');$('modal-card').innerHTML=html;$('modal').classList.remove('hidden');$('modal-card').querySelector('button:not(:disabled),input,select')?.focus();syncUI();}
function close(resume=true){modalMode=null;$('modal').classList.add('hidden');if(!online&&!engine.state.ended)engine.state.running=resume;audio.unlock();syncUI();}
function btn(id,fn){const el=$(id);if(el)el.onclick=fn;}
async function busy(el,fn){if(el?.disabled)return;const label=el?.textContent;if(el){el.disabled=true;el.textContent='รอสักครู่…';}try{await fn();}catch(e){toast(e.message,true);}finally{if(el?.isConnected){el.disabled=false;el.textContent=label;}}}
function choiceCards(shop=false){return '<div class="dock-select">'+PLAYABLE.map(t=>{const d=TYPES[t],owned=profile.owned.includes(t),loan=!shop&&chosenMission===2&&t==='battleship';return '<button class="ship-choice '+(chosenType===t?'chosen ':'')+(!owned&&!loan?'locked':'')+'" data-type="'+t+'"><b>'+d.name+'</b><span>'+d.label+'</span><span>HP '+d.hp+' · '+Math.round(d.speed*27)+' kn</span><em>'+(!owned?(loan?'ให้ยืมในภารกิจ 3':d.price.toLocaleString()+' CR'):t===chosenType?'เรือที่เลือก':'เป็นเจ้าของแล้ว')+'</em></button>';}).join('')+'</div>';}
function wireChoices(callback,shop=false){$('modal-card').querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{const t=b.dataset.type;if(!profile.owned.includes(t)&&!(chosenMission===2&&t==='battleship'&&!shop)){if(shop){const r=buy(profile,'ship',t);if(!r.ok){toast(r.reason,true);return;}persistProfile();toast('ซื้อ '+TYPES[t].name+' แล้ว');}else{toast('ซื้อเรือลำนี้ได้ที่ร้านค้า',true);return;}}chosenType=t;if(profile.owned.includes(t)){profile.selected=t;persistProfile();}audio.effect('click');callback();});}
function menu(){if(online){lobby();return;}chosenMission=Math.min(chosenMission,profile.unlockedMission);show('<div class="menu-top"><div><span class="modal-eyebrow">NAVAL ACTION / CO-OP 1–4</span><h1 id="modal-title">IRON TIDE <span style="color:var(--cyan)">II</span></h1></div><div class="wallet"><small>YOUR CREDITS</small>'+profile.credits.toLocaleString()+' CR</div></div><p>ขับเรือรบของคุณ ฝ่าการรุกรานจากต่างดาว<br>พันธมิตร AI พร้อมรบเคียงข้าง หรือชวนเพื่อนมาควบคุมเรือคนละลำ</p>'+choiceCards()+'<div class="loadout-summary"><span>WASD ขับเรือ</span><span>L ล็อกหลายเป้า</span><span>G ปืน · M จรวด · T ตอร์ปิโด</span><span>แมพ 36 × 36</span></div><div class="menu-fields"><div class="field"><label for="pilot-name">ชื่อผู้เล่น</label><input id="pilot-name" maxlength="24" value="'+esc(nickname)+'"></div><div class="field grow"><label for="mission-select">ภารกิจ</label><select id="mission-select">'+MISSIONS.map((m,i)=>'<option value="'+i+'" '+(i===chosenMission?'selected ':'')+(i>profile.unlockedMission?'disabled':'')+'>'+String(i+1).padStart(2,'0')+' '+m.name+(i>profile.unlockedMission?' · ยังไม่ปลดล็อก':'')+'</option>').join('')+'</select></div><div class="field"><label for="difficulty">ความยาก</label><select id="difficulty"><option value="easy">ฝึกบัญชาการ</option><option value="normal">ปกติ</option><option value="hard">ศึกเต็มกำลัง</option></select></div></div><div class="modal-actions"><button class="primary" id="start-solo">เริ่มภารกิจ →</button><button id="open-rooms">เล่นกับเพื่อน</button><button id="open-shop">อู่เรือ / ร้านค้า</button>'+(lastSave?'<button id="resume-save">เล่นต่อจากเซฟ</button>':'')+'</div><div class="menu-secondary"><button id="menu-help">วิธีเล่น</button><button id="menu-audio">เสียง / ดนตรี</button><button id="export-profile">สำรองข้อมูล</button><button id="import-profile">โหลดข้อมูล / เซฟ</button><button id="reconnect-room">กลับเข้าห้องล่าสุด</button></div><p class="fine-print">FLEET COMMAND 2.0 · เล่นคนเดียวแบบออฟไลน์ได้ · โหมด Co-op ใช้เซิร์ฟเวอร์ห้องออนไลน์</p>'+(!view.gl?'<p class="connection-note">เครื่องนี้ยังแสดงภาพ 3D ไม่ได้ เกมยังเล่นผ่านแผนที่ยุทธวิธีได้</p>':''),'menu',true);
 $('difficulty').value=difficulty;$('difficulty').onchange=e=>difficulty=e.target.value;$('pilot-name').onchange=e=>{nickname=e.target.value.trim().slice(0,24)||'กัปตัน';write('iron-tide-name-v2',nickname);};$('mission-select').onchange=e=>{chosenMission=Number(e.target.value);if(!profile.owned.includes(chosenType)&&chosenMission!==2)chosenType=profile.selected;menu();};wireChoices(menu);
 btn('start-solo',()=>{nickname=$('pilot-name').value.trim().slice(0,24)||'กัปตัน';write('iron-tide-name-v2',nickname);startSolo();});btn('open-shop',()=>shop(menu));btn('open-rooms',roomsScreen);btn('menu-help',()=>help(menu));btn('menu-audio',()=>settings(menu));btn('export-profile',exportData);btn('import-profile',importData);
 btn('resume-save',()=>{if(engine.import(lastSave)){hasSession=true;selectedTarget=null;lastEnd=null;if(engine.state.ended)result();else close();}else toast('เซฟนี้อ่านไม่ได้หรือเป็นเวอร์ชันเก่า',true);});
 btn('reconnect-room',e=>busy(e.currentTarget,async()=>{if(!await net.reconnectStored())throw Error('ไม่มีห้องที่เคยเข้าค้างไว้');online=true;showConnecting();}));
}
function startSolo(){online=false;hasSession=true;lastEnd=null;selectedTarget=null;localAim=null;engine.start(chosenMission,difficulty,[pilot()]);view.poses.clear();const m=MISSIONS[chosenMission];show('<span class="modal-eyebrow">OPERATION 0'+(chosenMission+1)+' / '+m.subtitle+'</span><h2 id="modal-title">'+m.name+'</h2><p>'+m.brief+'</p><div class="mission-goal"><b>เป้าหมาย</b><p>'+m.goal+'</p><span>เวลาสูงสุด '+m.duration/60+' นาที · เรือของคุณ '+TYPES[chosenType].name+'</span></div><p>'+m.tip+'</p><div class="modal-actions"><button class="primary" id="launch">เข้าปฏิบัติการ →</button><button id="brief-back">กลับไปเลือกเรือ</button></div>','brief');btn('launch',()=>{close();saveGame();toast('กด W เพิ่มคันเร่ง · คลิกศัตรูแล้ว L ล็อกเป้า');});btn('brief-back',menu);}
function shop(back=menu){const shopType=profile.owned.includes(chosenType)?chosenType:profile.selected;chosenType=shopType;profile.selected=shopType;const u=profile.upgrades[shopType]||{};show('<div class="menu-top"><div><span class="modal-eyebrow">FLEET DOCKYARD</span><h2 id="modal-title">อู่เรือและร้านค้า</h2></div><div class="wallet"><small>AVAILABLE</small>'+profile.credits.toLocaleString()+' CR</div></div><p>ซื้อเรือจากชื่อด้านล่าง หรือเลือกเรือที่มีอยู่เพื่ออัปเกรด อุปกรณ์ใหม่เริ่มใช้ในรอบถัดไป</p>'+choiceCards(true)+'<div class="upgrade-grid">'+Object.entries(UPGRADES).map(([k,v])=>{const level=u[k]||0,max=k==='locks'?Math.min(4,6-TYPES[shopType].locks):4,unsupported=k==='torpedo'&&!TYPES[shopType].torpedoes;return '<div class="upgrade-card"><h3>'+v.name+'</h3><div class="level-pips">'+Array.from({length:max},(_,i)=>i).map(i=>'<i class="'+(i<level?'filled':'')+'"></i>').join('')+'</div><p>'+v.text+'</p><button data-upgrade="'+k+'" '+(level>=max||unsupported?'disabled':'')+'>'+(unsupported?'เรือลำนี้ไม่รองรับ':level>=max?'ระดับสูงสุด':(v.cost*(level+1)).toLocaleString()+' CR · อัปเกรด')+'</button></div>';}).join('')+'</div><div class="modal-actions"><button class="primary" id="shop-back">เสร็จแล้ว</button><button id="shop-export">สำรองข้อมูล</button></div>','shop',true);wireChoices(()=>shop(back),true);
 $('modal-card').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const r=buy(profile,'upgrade',b.dataset.upgrade);if(!r.ok){toast(r.reason,true);return;}persistProfile();audio.effect('lock');shop(back);});btn('shop-export',exportData);btn('shop-back',async()=>{persistProfile();if(online&&['waiting','finished'].includes(room?.status)){try{await net.roomAction('loadout',pilot());}catch(e){toast(e.message,true);return;}}if(online&&room?.status==='waiting')lobby();else back();});
}
function settings(back=null){const wasRunning=engine.state.running;const go=back||(()=>close(wasRunning));show('<span class="modal-eyebrow">AUDIO CONTROL</span><h2 id="modal-title">เสียงและดนตรี</h2><p>ดนตรีจะเพิ่มจังหวะเมื่อการรบเข้มข้น ปรับแยกหรือปิดเสียงทั้งหมดได้</p>'+[['master','เสียงหลัก'],['music','ดนตรี'],['effects','เอฟเฟกต์ / ทะเล']].map(([k,label])=>'<label class="settings-row"><span>'+label+'</span><input type="range" min="0" max="100" value="'+Math.round(prefs[k]*100)+'" data-volume="'+k+'"><output id="vol-'+k+'">'+Math.round(prefs[k]*100)+'%</output></label>').join('')+'<label class="settings-check"><input id="mute-all" type="checkbox" '+(prefs.mute?'checked':'')+'>ปิดเสียงทั้งหมด</label><div class="modal-actions"><button class="primary" id="audio-back">กลับ</button><button id="audio-test">ลองเสียง</button></div>','settings');$('modal-card').querySelectorAll('[data-volume]').forEach(el=>el.oninput=()=>{const k=el.dataset.volume;prefs[k]=Number(el.value)/100;$('vol-'+k).textContent=el.value+'%';audio.settings=prefs;audio.unlock();audio.apply();write('iron-tide-audio-v2',prefs);});$('mute-all').onchange=e=>{prefs.mute=e.target.checked;audio.settings=prefs;audio.apply();write('iron-tide-audio-v2',prefs);syncUI();};btn('audio-back',go);btn('audio-test',()=>{audio.unlock();audio.effect('fire','shell');});}
function help(back=null){const run=engine.state.running;show('<span class="modal-eyebrow">CAPTAIN’S HANDBOOK</span><h2 id="modal-title">ขับเรือและใช้อาวุธ</h2><div class="help-grid"><p><b>W / S — คันเร่ง</b><br>กดค้างเพิ่มหรือลดคันเร่ง เรือมีแรงเฉื่อย ปล่อยปุ่มแล้วความเร็วไม่หยุดทันที</p><p><b>A / D — หางเสือ</b><br>เลี้ยวตามความเร็ว เรือใหญ่ใช้วงเลี้ยวกว้างกว่า<br>B หยุดเครื่อง · E เดินเรืออัตโนมัติไปพิกัด</p><p><b>คลิกทะเล / ศัตรู — เล็ง</b><br>ป้อมปืนจะค่อย ๆ หมุนหาเป้า วงเผื่อยิงบนภาพช่วยบอกตำแหน่งนำหน้าเรือศัตรู</p><p><b>G — ยิงปืนใหญ่</b><br>รอป้อมปืนเข้ามุม กระสุนมีวิถีโค้งและเวลาเดินทาง กดค้างเพื่อยิงเมื่อบรรจุเสร็จ</p><p><b>L — เพิ่ม / ปลดเป้าล็อก</b><br>เลือกศัตรูแล้วกด L รอ 1 วินาทีจนล็อกพร้อม ทำซ้ำกับหลายเป้า หรือ Shift+คลิก</p><p><b>M — ปล่อยจรวด</b><br>ยิงแบ่งไปยังทุกเป้าที่ล็อกพร้อม จำนวนเป้าขึ้นกับเรือและอัปเกรด</p><p><b>T — ตอร์ปิโด</b><br>เลือกเป้าในระยะ 16 ช่อง เดินทางใต้น้ำและเลี้ยวช้า ศัตรูที่กระโดดพ้นน้ำหลบได้</p><p><b>Q — โซนาร์</b><br>เปิดตำแหน่งศัตรูรัศมี 11 ช่อง นาน 15 วินาที จุดเหลืองบนเรดาร์เป็นพิกัดเก่า</p><p><b>F — ม่านสกัด / R — ซ่อม</b><br>สกัดกระสุน จรวดและโดรน ซ่อมตัวเรือ 35% ใน 10 วินาที มี 3 ชุดต่อลำ</p><p><b>X — ทิ้งสมอ</b><br>เฉพาะ VANGUARD หยุด 3 วินาที ปืนใหญ่นัดถัดไปแรงขึ้น 70% ภายใน 13 วินาที</p><p><b>Space — หยุด / เดินเวลา</b><br>เล่นคนเดียวพักได้ตลอด ออนไลน์เจ้าของห้องเป็นผู้พักเกมให้ทั้งทีม</p><p><b>Esc — เมนู / H — คู่มือ</b><br>ออนไลน์ยังเดินเวลาขณะเปิดเมนู ถ้าเรือคุณจมให้ชมเพื่อนและ AI ต่อจนจบรอบ</p></div><p class="fine-print">คุณควบคุมเรือของตัวเองเท่านั้น พันธมิตร AI เคลื่อนที่และยิงเอง · ปุ่มลัดใช้ตำแหน่งแป้นเดียวกันได้ขณะเปิดภาษาไทย</p><div class="modal-actions"><button class="primary" id="help-back">เข้าใจแล้ว</button></div>','help',true);btn('help-back',back||(()=>close(run)));}
function pauseMenu(){if(modalMode)return;saveGame();const host=online&&room?.host===net.playerId;show('<span class="modal-eyebrow">'+(online?'CO-OP OPERATIONS':'COMMAND PAUSED')+'</span><h2 id="modal-title">เมนูปฏิบัติการ</h2><p>'+MISSIONS[engine.state.mission].name+' · เหลือ '+fmt(engine.state.duration-engine.state.time)+'</p>'+(online?'<p class="connection-note">'+(host?'คุณเป็นเจ้าของห้อง ใช้ปุ่มพักทีมเพื่อหยุดเวลาทุกคน':'ออนไลน์ยังเดินเวลาขณะเปิดเมนู เจ้าของห้องพักเวลาให้ทีมได้')+'</p>':'')+'<div class="modal-actions"><button class="primary" id="resume">กลับเข้ารบ</button>'+(host?'<button id="team-pause">'+(engine.state.running?'พักทั้งทีม':'เดินเวลาทั้งทีม')+'</button>':'')+'<button id="pause-audio">เสียง / ดนตรี</button>'+(!online?'<button id="save-download">ดาวน์โหลดเซฟ</button><button id="retry">เริ่มภารกิจใหม่</button>':'')+'<button id="exit-battle">'+(online?'ออกจากห้อง':'กลับหน้าแรก')+'</button></div>','pause');btn('resume',()=>close());btn('team-pause',async()=>{try{await net.roomAction('pause',{running:!engine.state.running});close();}catch(e){toast(e.message,true);}});btn('pause-audio',()=>settings(()=>{modalMode=null;pauseMenu();}));btn('save-download',exportData);btn('retry',()=>confirmAction('เริ่มภารกิจใหม่?','ความคืบหน้าของรอบปัจจุบันจะเริ่มต้นใหม่',()=>{chosenMission=engine.state.mission;startSolo();},()=>{modalMode=null;pauseMenu();}));btn('exit-battle',()=>{if(online)confirmAction('ออกจากห้อง?','AI จะควบคุมเรือของคุณแทน',async()=>{await net.leave();online=false;room=null;hasSession=false;engine.start(0);menu();},()=>{modalMode=null;pauseMenu();});else menu();});}
function confirmAction(title,text,yes,no){show('<h2 id="modal-title">'+title+'</h2><p>'+text+'</p><div class="modal-actions"><button class="primary" id="yes">ยืนยัน</button><button id="no">กลับ</button></div>','confirm');btn('yes',yes);btn('no',no);}
function result(){const s=engine.state;if(!s.ended)return;const gained=reward(profile,s);if(gained)persistProfile();if(!online)saveGame();lastEnd=s.matchId;const win=s.ended.win;show('<span class="modal-eyebrow">'+(win?'MISSION COMPLETE':'MISSION ENDED')+'</span><h2 id="modal-title">'+(win?'กองเรือทำภารกิจสำเร็จ':'กลับอู่ เตรียมสู้รอบใหม่')+'</h2><p>'+esc(s.ended.reason)+'</p><div class="end-reward">+'+s.ended.credits.toLocaleString()+' <small>CR · รับรางวัลแล้ว</small></div><div class="result-stats"><div><b>'+s.stats.kills+'</b><span>เป้าหมายถูกทำลาย</span></div><div><b>'+fmt(s.time)+'</b><span>เวลาปฏิบัติการ</span></div><div><b>'+profile.credits.toLocaleString()+'</b><span>เครดิตคงเหลือ</span></div></div><p>นำเครดิตไปซื้อเรือหรืออัปเกรดอาวุธก่อนรอบถัดไป</p><div class="modal-actions"><button class="primary" id="result-shop">อู่เรือ / อัปเกรด</button>'+(!online?'<button id="next-mission">'+(win&&s.mission<2?'ภารกิจถัดไป':'เลือกภารกิจ')+'</button>':room?.host===net.playerId?'<button id="back-lobby">พาทีมกลับล็อบบี้</button>':'<span class="fine-print">รอเจ้าของห้องเปิดรอบใหม่</span>')+'<button id="result-exit">'+(online?'ออกจากห้อง':'หน้าแรก')+'</button></div>','result');btn('result-shop',()=>shop(result));btn('next-mission',()=>{chosenMission=win?Math.min(2,s.mission+1):s.mission;menu();});btn('back-lobby',e=>busy(e.currentTarget,()=>net.roomAction('lobby')));btn('result-exit',async()=>{if(online){await net.leave();online=false;room=null;hasSession=false;engine.start(0);}menu();});}
function exportData(){saveGame();persistProfile();const data={format:'iron-tide-backup',version:2,profile,save:online?null:lastSave},blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='IRON_TIDE_2_Save.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ดาวน์โหลดข้อมูลเรือ เครดิต และเซฟแล้ว');}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>1500000){toast('ไฟล์ใหญ่เกินไป',true);return;}try{const text=await f.text(),p=JSON.parse(text);if(p.format==='iron-tide-backup'&&p.version===2&&p.profile?.version===2){if(p.save){const check=new GameEngine();if(!check.import(p.save))throw Error('เซฟการรบไม่ถูกต้อง');}profile=cleanProfile(p.profile);lastSave=p.save||null;persistProfile();write('iron-tide-save-v2',lastSave);chosenType=profile.selected;toast('โหลดข้อมูลเรือและเซฟแล้ว');menu();}else if(p.format==='iron-tide-save'&&p.version===2){if(!engine.import(text))throw Error('เซฟไม่ถูกต้อง');lastSave=text;hasSession=true;write('iron-tide-save-v2',text);if(engine.state.ended)result();else close();}else throw Error('ไฟล์นี้ไม่ใช่เซฟของ IRON TIDE 2');}catch(e){toast(e.message||'เปิดเซฟไม่ได้',true);}};input.click();}
function showConnecting(){show('<span class="modal-eyebrow">CONNECTING TO FLEET</span><h2 id="modal-title">กำลังเข้าห้อง…</h2><p>กำลังรับรายชื่อผู้เล่นและสถานะกองเรือ</p><div class="modal-actions"><button id="cancel-connect">ยกเลิก</button></div>','connecting');btn('cancel-connect',async()=>{await net.leave();online=false;room=null;menu();});}
function serverValue(){return read('iron-tide-server-v2','')||window.IRON_TIDE_CONFIG?.serverUrl||(location.protocol==='http:'||location.protocol==='https:'?location.origin:'');}
function roomsScreen(){show('<span class="modal-eyebrow">MULTIPLAYER / CO-OP</span><h2 id="modal-title">ค้นหาห้องกองเรือ</h2><p>เลือกเซิร์ฟเวอร์เดียวกับเพื่อน แล้วสร้างห้องหรือเข้าด้วยรหัส 6 ตัว</p><div class="menu-fields"><div class="field grow"><label for="server-url">ที่อยู่เซิร์ฟเวอร์ห้อง</label><input id="server-url" type="url" placeholder="https://your-game-server.example" value="'+esc(serverValue())+'"></div><button id="connect-server">เชื่อมต่อ / รีเฟรช</button></div><p class="connection-note">ใช้ URL เซิร์ฟเวอร์เกมที่เปิดใช้งานแล้ว หากลงหน้าเกมบน GitHub Pages ให้ใส่ URL เซิร์ฟเวอร์แยกตามคู่มือใน ZIP</p><div class="menu-fields"><div class="field grow"><label for="room-name">ชื่อห้องใหม่</label><input id="room-name" maxlength="32" value="กองเรือของ '+esc(nickname)+'"></div><label class="settings-check"><input id="private-room" type="checkbox">เข้าด้วยรหัสเท่านั้น</label><button id="create-room">สร้างห้อง</button></div><div class="menu-fields"><div class="field"><label for="join-code">รหัสห้อง</label><input id="join-code" maxlength="6" placeholder="ABC123" style="text-transform:uppercase"></div><button id="join-code-btn">เข้าด้วยรหัส</button></div><div id="rooms-list" class="rooms-list"><p class="empty-hint">กดเชื่อมต่อเพื่อแสดงห้องที่เปิดอยู่</p></div><div class="modal-actions"><button id="rooms-back">กลับ</button></div>','rooms',true);
 const configure=()=>{const val=$('server-url').value.trim();if(!val)throw Error('ใส่ที่อยู่เซิร์ฟเวอร์ห้องก่อน');net.setBase(val);write('iron-tide-server-v2',net.base);};
 const refresh=async()=>{configure();const health=await net.health();if(health.version!==2)throw Error('เซิร์ฟเวอร์ต้องเป็น IRON TIDE 2');const list=await net.rooms();if(!$('rooms-list'))return;$('rooms-list').innerHTML=list.length?list.map(r=>'<div class="room-row"><b>'+esc(r.name)+'<small>'+esc(MISSIONS[r.mission]?.name||'ภารกิจ')+' · '+r.code+'</small></b><span>'+r.members.length+'/4</span><button data-join="'+r.code+'" '+(r.status!=='waiting'||r.members.length>=4?'disabled':'')+'>'+(r.status==='waiting'?'เข้าร่วม':'กำลังรบ')+'</button></div>').join(''):'<p class="empty-hint">ยังไม่มีห้อง สร้างห้องแรกแล้วส่งรหัสให้เพื่อนได้เลย</p>';$('rooms-list').querySelectorAll('[data-join]').forEach(b=>b.onclick=()=>busy(b,async()=>{await net.join(b.dataset.join,pilot());online=true;showConnecting();}));toast('เชื่อมต่อเซิร์ฟเวอร์แล้ว');};
 btn('connect-server',e=>busy(e.currentTarget,refresh));btn('create-room',e=>busy(e.currentTarget,async()=>{configure();await net.create({name:$('room-name').value,private:$('private-room').checked,mission:chosenMission,difficulty,pilot:pilot()});online=true;lastEvents=0;showConnecting();}));btn('join-code-btn',e=>busy(e.currentTarget,async()=>{configure();const code=$('join-code').value.toUpperCase().trim();if(!/^[A-F0-9]{6}$/.test(code))throw Error('กรอกรหัสห้อง 6 ตัวให้ถูกต้อง');await net.join(code,pilot());online=true;lastEvents=0;showConnecting();}));btn('rooms-back',menu);
}
function lobby(){if(!room){showConnecting();return;}const me=room.members.find(m=>m.id===net.playerId),host=room.host===net.playerId;if(!me)return;show('<div class="menu-top"><div><span class="modal-eyebrow">FLEET READY ROOM</span><h2 id="modal-title">'+esc(room.name)+'</h2></div><div class="wallet">'+room.members.length+' / 4</div></div><p>ส่งรหัสนี้ให้เพื่อน ทั้งหมดต้องเชื่อมต่อเซิร์ฟเวอร์เดียวกัน</p><div class="room-code">'+room.code+'</div><div class="lobby-slots">'+[0,1,2,3].map(i=>{const m=room.members[i];return '<div class="lobby-slot"><span class="pilot-dot">'+(m?(m.ready?'พร้อมรบ':'กำลังเตรียมตัว'):'AI พันธมิตร')+'</span><p>'+esc(m?.name||'ที่ว่าง')+'</p><small>'+(m?TYPES[m.type].name:'AI ควบคุมแทน')+'</small><small>'+(m?(m.connected?'เชื่อมต่อแล้ว':'รอการเชื่อมต่อ'):'เพื่อนเข้าร่วมได้')+'</small></div>';}).join('')+'</div><div class="menu-fields"><div class="field grow"><label for="lobby-mission">ภารกิจ</label><select id="lobby-mission" '+(!host?'disabled':'')+'>'+MISSIONS.map((m,i)=>'<option value="'+i+'" '+(i===room.mission?'selected':'')+'>'+m.name+'</option>').join('')+'</select></div><div class="field"><label for="lobby-difficulty">ความยาก</label><select id="lobby-difficulty" '+(!host?'disabled':'')+'><option value="easy">ฝึกบัญชาการ</option><option value="normal">ปกติ</option><option value="hard">ศึกเต็มกำลัง</option></select></div></div><div class="modal-actions"><button class="primary" id="ready-btn">'+(me.ready?'ยกเลิกพร้อม':'พร้อมรบ')+'</button>'+(host?'<button id="start-room" '+(!room.members.every(x=>x.ready&&x.connected)?'disabled':'')+'>เริ่มรบทั้งทีม →</button>':'')+'<button id="lobby-shop">เลือกเรือ / อัปเกรด</button><button id="copy-code">คัดลอกรหัส</button><button id="leave-room">ออกจากห้อง</button></div><p class="fine-print">ผู้เล่นแต่ละคนควบคุมเรือหนึ่งลำ · AI เติมช่องว่าง · เข้าห้องได้ก่อนเริ่มรอบ · หลุดชั่วคราวกลับมาได้ภายใน 90 วินาที</p>','lobby',true);
 $('lobby-difficulty').value=room.difficulty;const config=async()=>{try{await net.roomAction('configure',{mission:Number($('lobby-mission').value),difficulty:$('lobby-difficulty').value});}catch(e){toast(e.message,true);}};$('lobby-mission').onchange=config;$('lobby-difficulty').onchange=config;btn('ready-btn',e=>busy(e.currentTarget,()=>net.roomAction('ready',{ready:!me.ready})));btn('start-room',e=>busy(e.currentTarget,()=>net.roomAction('start')));btn('lobby-shop',()=>shop(lobby));btn('copy-code',async()=>{try{await navigator.clipboard.writeText(room.code);toast('คัดลอกรหัสแล้ว');}catch(e){toast('รหัสห้อง: '+room.code);}});btn('leave-room',async()=>{await net.leave();online=false;room=null;hasSession=false;engine.start(0);menu();});
}
net.onNotice=text=>toast(text,true);
net.onStatus=status=>{$('connection-status').textContent=status==='online'?'CO-OP LIVE':status==='reconnecting'?'RECONNECTING':status==='connecting'?'CONNECTING':'OFFLINE';if(online&&status==='offline'&&net.closed){toast('การเชื่อมต่อห้องสิ้นสุดแล้ว เปิดเมนูเพื่อออกจากห้อง',true);}};
net.onFrame=packet=>{online=true;hadConnection=true;room=packet.room;const roomKey=JSON.stringify(room);if(packet.state){engine.state=packet.state;engine.state.selected=packet.shipId;const sh=myShip();if(sh){if(localAim)sh.aim={...localAim};engine.state.target=sh.aim;}for(const e of packet.events||[]){if(e.seq>lastEvents){handleEvent(e);lastEvents=e.seq;}}if(packet.state.ended){if(lastEnd!==packet.state.matchId)result();}else if(['lobby','connecting','rooms','menu'].includes(modalMode)){lastEnd=null;localAim=null;view.poses.clear();close();toast('เข้ารบแล้ว คุณบังคับ '+(sh?TYPES[sh.type].name:'เรือของตัวเอง'));}}
 else if(room.status==='waiting'){lastEnd=null;if(modalMode!=='shop'&&(modalMode!=='lobby'||roomKey!==lastRoomView))lobby();}lastRoomView=roomKey;syncUI();};
function handleEvent(e){audio.effect(e.type,e.kind);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){if(e.type==='fire'&&(e.ship?.id||e.shipId)===engine.state.selected)view.shake=.35;if(e.type==='hit'&&(e.ship?.id||e.shipId)===engine.state.selected)view.shake=.7;if(e.type==='sunk')view.shake=.6;}if(e.type==='drone')toast('ตรวจพบโดรนใบจักร — เตรียมม่านสกัด');if(e.type==='domeDown')toast('โดมล่มแล้ว! โจมตีศูนย์ส่งสัญญาณได้');if(e.type==='notice')toast(e.text,e.error);if(e.type==='end'&&!online)result();}
engine.listener=handleEvent;
const ACTIONS=[{id:'gun',key:'G',label:'ปืนใหญ่',icon:'⌖',cd:'gunCD'},{id:'missile',key:'M',label:'จรวด',icon:'↗',cd:'missileCD'},{id:'torpedo',key:'T',label:'ตอร์ปิโด',icon:'≈',cd:'torpedoCD'},{id:'scan',key:'Q',label:'โซนาร์',icon:'◎',cd:'scanCD'},{id:'defense',key:'F',label:'ม่านสกัด',icon:'◇',cd:'defenseCD'},{id:'repair',key:'R',label:'ซ่อมเรือ',icon:'+',cd:'repairCD'},{id:'move',key:'E',label:'ไปพิกัด',icon:'⇢'},{id:'anchor',key:'X',label:'ทิ้งสมอ',icon:'⚓',cd:'anchorCD'}];
$('action-dock').innerHTML=ACTIONS.map(a=>'<button id="action-'+a.id+'" class="action-btn '+(a.id==='gun'?'fire':'')+'" title="'+a.label+' ['+a.key+']"><kbd>'+a.key+'</kbd><span class="action-icon" aria-hidden="true">'+a.icon+'</span><span>'+a.label+'</span><small></small></button>').join('');
function issue(action,targetId=null,silent=false){if(modalMode||engine.state.ended)return;const sh=myShip();if(!sh||sh.hp<=0){if(!silent)toast('เรือของคุณจมแล้ว กำลังชมการรบของทีม',true);return;}audio.unlock();if(online){net.queue(action,targetId||undefined);}else{const r=engine.action(action,sh.id,{targetId:targetId||undefined});if(!r.ok&&!silent)toast(r.reason,true);else if(r.ok&&action==='lock')audio.effect('lock');}syncUI();}
for(const a of ACTIONS)btn('action-'+a.id,()=>issue(a.id));btn('lock-btn',()=>issue('lock',selectedTarget));btn('clear-locks',()=>issue('clearLocks'));
function pick(p,multi=false){if(modalMode)return;const sh=myShip();if(!sh||sh.hp<=0)return;const target=engine.state.ships.filter(e=>e.team==='enemy'&&e.hp>0&&engine.isVisible(e)&&dist(e,p)<1.3).sort((a,b)=>dist(a,p)-dist(b,p))[0];selectedTarget=target?.id||null;engine.setTarget(target?.x??p.x,target?.y??p.y,sh.id);localAim={...sh.aim};audio.effect('click');if(multi&&target)issue('lock',target.id);syncUI();}
view.onPick=pick;
radar.addEventListener('pointerdown',e=>{const r=radar.getBoundingClientRect(),x=((e.clientX-r.left)/r.width*400-23)/354*GRID,y=((e.clientY-r.top)/r.height*400-23)/354*GRID;if(x>=0&&y>=0&&x<GRID&&y<GRID)pick({x,y},e.shiftKey);});
function applyCoord(){const p=parseCoord($('coord-input').value);if(!p){toast('พิกัดอยู่ระหว่าง A1 ถึง AJ36 เช่น S22',true);return;}pick(p);}
btn('set-coord',applyCoord);$('coord-input').onkeydown=e=>{if(e.key==='Enter')applyCoord();};
function syncUI(){const s=engine.state;if(!s)return;const sh=myShip(),m=MISSIONS[s.mission];$('mission-label').textContent='OPERATION 0'+(s.mission+1)+' / 03';$('mission-name').textContent=m.name;$('objective').textContent=s.objectiveOpen?'แกนโดมพังแล้ว — ทำลายศูนย์ส่งสัญญาณและศัตรูที่เหลือ':m.goal;$('timer').textContent=fmt(s.duration-s.time);$('timer').style.color=s.duration-s.time<60?'var(--red)':'';$('stage-state').textContent=s.ended?(s.ended.win?'ภารกิจสำเร็จ':'จบปฏิบัติการ'):s.running?'การปะทะกำลังดำเนินอยู่':'หยุดเวลา · รอคำสั่ง';if(!online)$('connection-status').textContent='SOLO';$('sound-btn').textContent=prefs.mute?'เสียง: ปิด':'เสียง';$('sound-btn').setAttribute('aria-pressed',!prefs.mute);$('quality-btn').textContent='ภาพ: '+['ต่ำ','กลาง','สูง'][view.quality];$('my-ship-name').textContent=sh?TYPES[sh.type].name:'SPECTATOR';$('speed-value').innerHTML=(Math.abs(sh?.velocity||0)*27).toFixed(1)+' <small>kn</small>';$('throttle-fill').style.width=(Math.abs(sh?.throttle||0)*100)+'%';$('throttle-fill').style.background=sh?.throttle<0?'var(--amber)':'var(--cyan)';$('helm-status').textContent=sh?'คันเร่ง '+Math.round(sh.throttle*100)+'%'+(sh.dest?' · เดินเรืออัตโนมัติ':''):'ชมการรบของพันธมิตร';$('status-line').textContent=sh?sh.name+' / '+coord(sh.x,sh.y)+' / '+(sh.owner?'คุณเป็นผู้บังคับ':'AI'):'ชมการรบของทีม';
 const targets=s.ships.filter(e=>e.team==='enemy'&&e.hp>0&&engine.isVisible(e));$('contact-count').textContent=targets.length+' CONTACTS';const ps=s.ships.filter(e=>e.team==='player'&&e.hp>0);$('fleet-status').textContent=ps.length+' VESSELS';$('fleet-list').innerHTML=ps.map(p=>'<div class="fleet-card '+(p.id===s.selected?'mine':'')+'"><div class="fleet-head"><span>'+esc(TYPES[p.type].name)+'</span><span>'+Math.ceil(p.hp)+'<small> / '+p.maxHP+'</small></span></div><div class="fleet-type"><span>'+esc(p.id===s.selected?'คุณบังคับ':p.owner?p.name:'AI พันธมิตร')+'</span><span>'+(p.defenseUntil>s.time?'สกัดอาวุธ':p.repairUntil>s.time?'กำลังซ่อม':Math.abs(p.velocity)>.1?'กำลังแล่น':'พร้อมรบ')+'</span></div><div class="hp-track"><div class="hp-fill" style="width:'+p.hp/p.maxHP*100+'%;background:'+(p.hp<p.maxHP*.35?'var(--red)':'var(--cyan)')+'"></div></div></div>').join('');
 $('lock-count').textContent=(sh?.locks.length||0)+' / '+(sh?.lockLimit||0);const locks=(sh?.locks||[]).map(id=>s.ships.find(e=>e.id===id&&e.hp>0)).filter(Boolean);const lockHtml=locks.length?locks.map((e,i)=>'<div class="lock-entry"><b>'+(i+1)+'. '+esc(e.name)+'</b><span>'+((sh.lockProgress[e.id]||0)>=1?'LOCKED':Math.round((sh.lockProgress[e.id]||0)*100)+'%')+'</span><button data-unlock="'+e.id+'" aria-label="ปลดเป้า '+esc(e.name)+'">×</button></div>').join(''):'<p class="empty-hint">คลิกศัตรูแล้วกด L เพื่อเพิ่มเป้า<br>กด M ยิงทุกเป้าที่ล็อกพร้อม</p>';if($('lock-list').innerHTML!==lockHtml){$('lock-list').innerHTML=lockHtml;$('lock-list').querySelectorAll('[data-unlock]').forEach(b=>b.onclick=()=>issue('lock',Number(b.dataset.unlock)));}
 for(const a of ACTIONS){const b=$('action-'+a.id),cd=sh&&a.cd?sh[a.cd]:0;let detail=a.id==='missile'?'เหลือ '+(sh?.missiles||0)+' นัด':a.id==='torpedo'?'เหลือ '+(sh?.torpedoes||0)+' ลูก':a.id==='repair'?'เหลือ '+(sh?.repairs||0)+' ชุด':a.id==='gun'?'ระยะ '+(sh?.range||0):a.id==='anchor'?'+70% นัดถัดไป':a.id==='scan'?'รัศมี 11 ช่อง':a.id==='defense'?'ป้องกัน 8.5 วิ':'เลือกจุดหมาย';b.querySelector('small').textContent=cd>.01?Math.ceil(cd)+' วิ':detail;b.disabled=!sh||sh.hp<=0||!!s.ended||cd>.01||(a.id==='missile'&&!sh?.missiles)||(a.id==='torpedo'&&!sh?.torpedoes)||(a.id==='repair'&&(!sh?.repairs||sh.hp>=sh.maxHP))||(a.id==='anchor'&&sh?.type!=='battleship');b.classList.toggle('active',!!sh&&(a.id==='move'&&!!sh.dest||a.id==='defense'&&sh.defenseUntil>s.time||a.id==='repair'&&sh.repairUntil>s.time));}
 if(sh){if(document.activeElement!==$('coord-input'))$('coord-input').value=coord(sh.aim.x,sh.aim.y);const err=Math.abs(Math.atan2(Math.sin(Math.atan2(sh.aim.x-sh.x,sh.aim.y-sh.y)-sh.turret),Math.cos(Math.atan2(sh.aim.x-sh.x,sh.aim.y-sh.y)-sh.turret)));$('target-status').textContent='ระยะ '+dist(sh,sh.aim).toFixed(1)+' · '+(err>.13?'หมุนป้อมปืน':'ป้อมปืนพร้อม');}
 $('radio-log').innerHTML=s.logs.slice(0,4).map(e=>'<div class="radio-entry '+(e.tone==='danger'?'danger':e.tone==='good'?'good':'')+'"><time>'+fmt(e.t)+'</time><span>'+esc(e.text)+'</span></div>').join('');
}
function radarDraw(){const s=engine.state,c=rctx,pad=23,size=354,k=size/GRID,pt=(x,y)=>[pad+x*k,pad+y*k];c.clearRect(0,0,400,400);c.fillStyle='#071923';c.fillRect(0,0,400,400);c.lineWidth=1;c.strokeStyle='#1b3946';for(let i=0;i<=GRID;i++){c.globalAlpha=i%3===0?1:.3;c.beginPath();c.moveTo(pad+i*k,pad);c.lineTo(pad+i*k,pad+size);c.moveTo(pad,pad+i*k);c.lineTo(pad+size,pad+i*k);c.stroke();}c.globalAlpha=1;c.fillStyle='#7297a7';c.font='10px Consolas,monospace';c.textAlign='center';c.textBaseline='middle';for(let i=0;i<GRID;i+=3){c.fillText(col(i),pad+(i+.5)*k,12);c.fillText(i+1,12,pad+(i+.5)*k);}
 c.save();c.beginPath();c.rect(pad,pad,size,size);c.clip();
 for(const o of s.islands){const [x,y]=pt(o.x,o.y);c.fillStyle='#365448';c.strokeStyle='#6c8d72';c.beginPath();c.arc(x,y,o.r*k,0,TAU);c.fill();c.stroke();}
 for(const b of s.buoys){const [x,y]=pt(b.x,b.y);c.fillStyle='#c4a55d';c.fillRect(x-2,y-2,4,4);const age=s.time-(b.pulseAt||0);if(age<3){c.strokeStyle='rgba(227,185,101,'+(1-age/3)*.3+')';c.beginPath();c.arc(x,y,age*2*k,0,TAU);c.stroke();}}
 const ghosts=s.contacts||s.ships.filter(e=>e.team==='enemy'&&e.hp>0&&!engine.isVisible(e)&&e.lastKnown&&s.time-e.lastKnownAt<22).map(e=>({id:e.id,x:e.lastKnown.x,y:e.lastKnown.y,at:e.lastKnownAt}));for(const e of ghosts){const [x,y]=pt(e.x,e.y);c.globalAlpha=Math.max(.2,1-(s.time-e.at)/22);c.strokeStyle='#f4bf72';c.strokeRect(x-4,y-4,8,8);}c.globalAlpha=1;
 const sh=myShip();if(sh){const [x,y]=pt(sh.x,sh.y);c.strokeStyle='#53d2e133';c.beginPath();c.arc(x,y,sh.range*k,0,TAU);c.stroke();if(sh.dest){const [xx,yy]=pt(sh.dest.x,sh.dest.y);c.setLineDash([3,4]);c.strokeStyle='#6adddf';c.beginPath();c.moveTo(x,y);c.lineTo(xx,yy);c.stroke();c.setLineDash([]);}}
 for(const e of s.ships){if(e.hp<=0||e.team==='enemy'&&!engine.isVisible(e))continue;const [x,y]=pt(e.x,e.y);c.fillStyle=e.team==='player'?(e.id===s.selected?'#d8fbff':'#69c3d2'):'#ff7c65';c.save();c.translate(x,y);c.rotate(-e.heading);if(['shield','uplink'].includes(e.type)){c.rotate(Math.PI/4);c.fillRect(-5,-5,10,10);}else{c.beginPath();c.moveTo(0,7);c.lineTo(4,-5);c.lineTo(-4,-5);c.closePath();c.fill();}c.restore();if(e.id===s.selected){c.strokeStyle='#d8fbff';c.beginPath();c.arc(x,y,10,0,TAU);c.stroke();}if(sh?.locks.includes(e.id)){c.strokeStyle='#ffce83';c.strokeRect(x-8,y-8,16,16);c.fillStyle='#ffce83';c.fillText(sh.locks.indexOf(e.id)+1,x+11,y-9);}if(e.jump){const [jx,jy]=pt(e.jump.tx,e.jump.ty);c.strokeStyle='#ff9a5799';c.beginPath();c.arc(jx,jy,9,0,TAU);c.stroke();}}
 for(const p of s.projectiles){if(p.age<0)continue;const [x,y]=pt(p.x,p.y);c.fillStyle=p.kind==='torpedo'?'#91e1c2':p.team==='player'?'#ffedba':'#ff6a43';c.fillRect(x-1.5,y-1.5,3,3);}
 for(const d of s.drones){const [x,y]=pt(d.x,d.y);c.strokeStyle='#ff6d3c';c.beginPath();c.arc(x,y,4,0,TAU);c.stroke();}
 if(sh){const [x,y]=pt(sh.aim.x,sh.aim.y);c.strokeStyle='#ffe0a0';c.beginPath();c.moveTo(x-6,y);c.lineTo(x+6,y);c.moveTo(x,y-6);c.lineTo(x,y+6);c.stroke();}c.restore();
}
const TAU=Math.PI*2;
function overlayDraw(){const w=overlay.clientWidth,h=overlay.clientHeight;if(overlay.width!==w||overlay.height!==h){overlay.width=w;overlay.height=h;}const c=octx;c.clearRect(0,0,w,h);if(!view.gl)return;const s=engine.state,sh=myShip();c.textAlign='center';c.font='11px Tahoma';
 for(const e of s.ships){if(e.hp<=0||e.team==='enemy'&&!engine.isVisible(e))continue;const p=view.project(e.x,e.y,1.5+(e.jump?.height||0));if(!p||p.x<0||p.y<145||p.x>w||p.y>h-140)continue;const own=e.team==='player',locked=sh?.locks.includes(e.id);c.fillStyle=own?'#b8edf2':'#ffb3a0';c.fillText((locked?'['+(sh.locks.indexOf(e.id)+1)+'] ':'')+(e.id===s.selected?'คุณ · ':'')+TYPES[e.type].name,p.x,p.y-10);c.fillStyle='#091c26bd';c.fillRect(p.x-24,p.y,48,4);c.fillStyle=own?'#78dce7':'#ff7a61';c.fillRect(p.x-24,p.y,48*e.hp/e.maxHP,4);
  if(locked){c.strokeStyle='#ffc575';c.setLineDash(sh.lockProgress[e.id]>=1?[]:[4,4]);c.strokeRect(p.x-32,p.y-25,64,43);c.setLineDash([]);}
 }
 const t=s.ships.find(e=>e.id===selectedTarget&&e.hp>0);if(sh&&t&&engine.isVisible(t)){const flight=1.3+dist(sh,t)*.11,lead=view.project(t.x+(t.vx||0)*flight,t.y+(t.vy||0)*flight,.2);if(lead){c.strokeStyle='#ffe1a3aa';c.setLineDash([2,4]);c.beginPath();c.arc(lead.x,lead.y,12,0,TAU);c.stroke();c.setLineDash([]);}}
}
function pauseToggle(){if(modalMode)return;if(online){if(room?.host!==net.playerId){toast('เจ้าของห้องเป็นผู้พักเวลาทั้งทีม');return;}net.roomAction('pause',{running:!engine.state.running}).catch(e=>toast(e.message,true));}else{engine.state.running=!engine.state.running;if(!engine.state.running){stopKeys();saveGame();toast('พักเวลาแล้ว กด Space เพื่อเดินเวลาต่อ');}else audio.unlock();}syncUI();}
btn('pause-btn',pauseMenu);btn('help-btn',()=>{if(!modalMode)help();});btn('sound-btn',()=>{if(!modalMode)settings();});btn('camera-btn',()=>{$('camera-btn').textContent='กล้อง: '+view.cameraMode();});btn('grid-btn',()=>{view.grid=!view.grid;$('grid-btn').classList.toggle('active',view.grid);$('grid-btn').setAttribute('aria-pressed',view.grid);});btn('quality-btn',()=>{view.quality=(view.quality+1)%3;write('iron-tide-quality-v2',view.quality);syncUI();});
document.querySelectorAll('[data-drive]').forEach(el=>{const code={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD'}[el.dataset.drive];el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);keys.add(code);el.classList.add('pressed');audio.unlock();});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>{keys.delete(code);el.classList.remove('pressed');});});
document.addEventListener('keydown',e=>{
 if(modalMode){if(e.code==='Escape'&&modalMode==='pause')close();if(e.code==='Tab'){const nodes=[...$('modal-card').querySelectorAll('button:not(:disabled),input,select,a[href]')],first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}
 if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||e.ctrlKey||e.altKey||e.metaKey)return;
 if(['KeyW','KeyS','KeyA','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();keys.add(e.code);audio.unlock();return;}
 if(e.code==='KeyG'){e.preventDefault();heldGun=true;if(!e.repeat)issue('gun');return;}if(e.repeat)return;
 if(e.code==='Space'){e.preventDefault();pauseToggle();return;}if(e.code==='Escape'){pauseMenu();return;}if(e.code==='KeyH'){help();return;}
 const action={KeyM:'missile',KeyT:'torpedo',KeyQ:'scan',KeyF:'defense',KeyR:'repair',KeyE:'move',KeyX:'anchor',KeyB:'stop',KeyL:'lock'}[e.code];if(action){e.preventDefault();issue(action,action==='lock'?selectedTarget:null);}
});
document.addEventListener('pointerdown',()=>audio.unlock(),{once:true});
document.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyG')heldGun=false;});
window.addEventListener('blur',stopKeys);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopKeys();if(!online&&engine.state.running){engine.state.running=false;saveGame();syncUI();}}});window.addEventListener('beforeunload',()=>{saveGame();persistProfile();});
if(!view.gl){const div=document.createElement('div');div.className='fallback-message';div.textContent='ภาพ 3D ไม่พร้อมใช้งาน — เล่นผ่านแผนที่ยุทธวิธีได้';$('world').after(div);}
function frame(now){const dt=last?Math.min((now-last)/1000,.1):.016;last=now;const sh=myShip(),up=keys.has('KeyW')||keys.has('ArrowUp'),down=keys.has('KeyS')||keys.has('ArrowDown'),left=keys.has('KeyA')||keys.has('ArrowLeft'),right=keys.has('KeyD')||keys.has('ArrowRight'),input={throttle:modalMode?0:Number(up)-Number(down),steer:modalMode?0:Number(right)-Number(left)};
 if(!online){if(sh)engine.input(sh.id,input);engine.tick(dt);}if(heldGun&&!modalMode&&sh&&sh.gunCD<=.01)issue('gun',null,true);
 netClock+=dt;if(online&&room?.status==='playing'&&netClock>.10){netClock=0;net.send(input,sh?.aim||engine.state.target);}
 view.render(dt);radarDraw();overlayDraw();audio.update(engine.state,sh);uiClock+=dt;saveClock+=dt;if(uiClock>.15){syncUI();uiClock=0;}if(saveClock>10){if(engine.state.running)saveGame();saveClock=0;}requestAnimationFrame(frame);
}
syncUI();menu();requestAnimationFrame(frame);
})();
